from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations
import heapq


def _resolver(data, preference, name_order):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=(name_order == "descending"))
    best_vector = None
    best = None

    def visit(pending, chosen, edges):
        nonlocal best_vector, best
        if not pending:
            # A package graph with any directed cycle is invalid.
            done, active = set(), set()

            def acyclic(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not acyclic(child) for child in edges.get(name, ())):
                    return False
                active.remove(name)
                done.add(name)
                return True

            if not all(acyclic(name) for name in chosen):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or (vector < best_vector if preference == "minimum" else vector > best_vector):
                best_vector = vector
                best = dict(chosen)
            return

        name, low, high = pending[0]
        rest = pending[1:]
        if name in chosen:
            version = chosen[name]
            if low <= version <= high:
                visit(rest, chosen, edges)
            return

        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        rows.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))
        for row in rows:
            next_chosen = dict(chosen)
            next_chosen[name] = row["version"]
            next_edges = dict(edges)
            active_deps = [dep for dep in row.get("deps", [])
                           if not dep.get("feature") or dep["feature"] in features]
            next_edges[name] = [dep["name"] for dep in active_deps]
            next_pending = list(rest)
            next_pending.extend((dep["name"], dep["min"], dep["max"]) for dep in active_deps)
            visit(next_pending, next_chosen, next_edges)

    initial = [(name, bounds[0], bounds[1]) for name, bounds in data["roots"].items()]
    visit(initial, {}, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _ledger(data):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        return (numerator + 5000) // 10000 if half_up else numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _schedule(data):
    jobs = [job for job in data["jobs"] if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        idset = set(ids)
        if not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distance = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _resolver(data, "minimum", "ascending"),
    "component_02": lambda data: _resolver(data, "maximum", "descending"),
    "component_03": lambda data: _resolver(data, "minimum", "descending"),
    "component_04": lambda data: _resolver(data, "maximum", "ascending"),
    "component_05": lambda data: _resolver(data, "minimum", "ascending"),
    "component_06": _ledger,
    "component_07": _schedule,
    "component_08": _routes,
}
